void backtrack(State state, List<Result> results) {
    if (isComplete(state)) {            // found a full solution
        results.add(snapshot(state));
        return;
    }
    for (Choice choice : choices(state)) {
        if (!isValid(choice, state)) continue;  // PRUNE invalid branches
        apply(choice, state);           // 1. CHOOSE
        backtrack(state, results);      // 2. EXPLORE
        undo(choice, state);            // 3. UN-CHOOSE (restore!)
    }
}
// The undo() after exploring is what makes this backtracking, not plain recursion.
