List<List<Integer>> subsets(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    backtrack(nums, 0, new ArrayList<>(), result);
    return result;
}
void backtrack(int[] nums, int start, List<Integer> cur, List<List<Integer>> res) {
    res.add(new ArrayList<>(cur));            // COPY, not the reference
    for (int i = start; i < nums.length; i++) {
        cur.add(nums[i]);                     // choose
        backtrack(nums, i + 1, cur, res);     // explore
        cur.remove(cur.size() - 1);           // un-choose
    }
}

// nums = {1,2}: [] , [1], [1,2], [2]  -> 2^2 = 4 subsets
