List<List<Integer>> combinationSum(int[] cand, int target) {
    Arrays.sort(cand);                       // enables early break
    List<List<Integer>> res = new ArrayList<>();
    backtrack(cand, target, 0, new ArrayList<>(), res);
    return res;
}
void backtrack(int[] c, int rem, int start, List<Integer> path, List<List<Integer>> res) {
    if (rem == 0) { res.add(new ArrayList<>(path)); return; }   // hit target
    for (int i = start; i < c.length; i++) {
        if (c[i] > rem) break;               // PRUNE: sorted, rest are larger
        path.add(c[i]);                      // choose
        backtrack(c, rem - c[i], i, path, res);  // i = allow reuse
        path.remove(path.size() - 1);        // un-choose
    }
}

// cand={2,3,6,7}, target=7 -> [2,2,3] and [7]
