int count = 0;
void solve(int r, int n, boolean[] col, boolean[] diag1, boolean[] diag2) {
    if (r == n) { count++; return; }                 // all rows placed
    for (int c = 0; c < n; c++) {
        int d1 = r - c + n, d2 = r + c;              // diagonal ids (offset)
        if (col[c] || diag1[d1] || diag2[d2]) continue;  // PRUNE conflicts
        col[c] = diag1[d1] = diag2[d2] = true;       // choose
        solve(r + 1, n, col, diag1, diag2);          // explore
        col[c] = diag1[d1] = diag2[d2] = false;      // un-choose
    }
}
// One queen per row + O(1) checks; diagonals via r-c and r+c.
