// Construct EVERY subset (the answer is the whole set of solutions)
void subsets(int[] nums, int i, List<Integer> cur, List<List<Integer>> res) {
    if (i == nums.length) { res.add(new ArrayList<>(cur)); return; }
    cur.add(nums[i]); subsets(nums, i + 1, cur, res); cur.remove(cur.size()-1);
    subsets(nums, i + 1, cur, res);     // exponential: 2^n results
}
