// Coin change: minimum coins for amount - OPTIMAL value via memoized subproblems
int coinChange(int[] coins, int amount) {
    int[] dp = new int[amount + 1];
    Arrays.fill(dp, amount + 1);
    dp[0] = 0;
    for (int a = 1; a <= amount; a++)
        for (int c : coins)
            if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);  // reuse dp[a-c]
    return dp[amount] > amount ? -1 : dp[amount];
}
// Each subproblem dp[a] computed once -> polynomial, not exponential.
